<template><SilkRoadWorkspace title="营销图片生成"><section class="head"><div><span>VISUAL GENERATION</span><h1>商品场景图与广告素材</h1><p>生成商品使用场景、主图、详情图、广告图和视频画面素材。</p></div><el-button @click="router.push('/media/video')">前往视频生成</el-button></section><section class="generator"><el-form label-position="top"><el-form-item label="关联营销项目"><el-select v-model="form.projectId" filterable placeholder="选择项目"><el-option v-for="item in projects" :key="item.id" :label="item.product_name" :value="String(item.id)"/></el-select></el-form-item><el-form-item label="素材类型"><el-radio-group v-model="form.type"><el-radio-button value="product_main">商品主图</el-radio-button><el-radio-button value="usage_scene">使用场景</el-radio-button><el-radio-button value="detail">详情图</el-radio-button><el-radio-button value="advertisement">广告图</el-radio-button></el-radio-group></el-form-item><el-form-item label="目标市场视觉要求"><el-input v-model="form.prompt" type="textarea" :rows="4" placeholder="描述商品、使用场景、构图、目标市场风格、画面比例和禁用元素"/></el-form-item><el-button type="primary" :loading="generating" :disabled="!form.projectId||!form.prompt" @click="generate">生成营销图片</el-button></el-form></section><h2 class="section-title">最近生成</h2><div v-loading="loading" class="media-grid"><article v-for="item in images" :key="item.id"><div><img v-if="item.image_url" :src="item.image_url" :alt="item.prompt"/><el-icon v-else><Picture /></el-icon></div><el-tag :type="item.status==='completed'?'success':item.status==='failed'?'danger':'warning'">{{ statusText(item.status) }}</el-tag><p>{{ item.prompt }}</p></article></div><el-empty v-if="!loading&&!images.length" description="暂无营销图片生成记录"/></SilkRoadWorkspace></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import{Picture}from'@element-plus/icons-vue';import{useRoute,useRouter}from'vue-router';import SilkRoadWorkspace from '@/layouts/SilkRoadWorkspace.vue';import{projectAPI}from'@/api/project';import{mediaGenerationAPI}from'@/api/media-generation';import type{MarketingProject}from'@/types/project';import type{ImageGeneration}from'@/types/image';const route=useRoute(),router=useRouter(),projects=ref<MarketingProject[]>([]),images=ref<ImageGeneration[]>([]),loading=ref(false),generating=ref(false),form=reactive({projectId:String(route.query.projectId||''),type:'usage_scene',prompt:''});const statusText=(s:string)=>({pending:'等待中',processing:'生成中',completed:'已完成',failed:'失败'}[s]||s);const load=async()=>{loading.value=true;try{projects.value=(await projectAPI.list({page_size:100})).items;if(!form.projectId&&projects.value[0])form.projectId=String(projects.value[0].id);images.value=(await mediaGenerationAPI.images.listByProject(form.projectId||undefined)).items||[]}finally{loading.value=false}};const generate=async()=>{generating.value=true;try{await mediaGenerationAPI.images.generateForProject({project_id:form.projectId,material_type:form.type,prompt:form.prompt});ElMessage.success('营销图片生成任务已提交');await load()}catch(e:any){ElMessage.error(e?.message||'图片生成失败')}finally{generating.value=false}};onMounted(load)</script>
<style scoped>.head{display:flex;align-items:end;justify-content:space-between;margin-bottom:22px}.head span{font-size:12px;letter-spacing:.16em;color:var(--accent);font-weight:800}.head h1{font-size:30px;margin:8px 0}.head p{color:var(--text-secondary)}.generator{padding:23px;border:1px solid var(--border-primary);border-radius:20px;background:var(--bg-card)}.generator .el-select{width:100%}.section-title{margin:28px 0 16px}.media-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:16px;min-height:100px}.media-grid article{padding:12px;border:1px solid var(--border-primary);border-radius:16px;background:var(--bg-card)}.media-grid article>div{height:170px;display:grid;place-items:center;background:var(--bg-muted);border-radius:11px;overflow:hidden;font-size:42px}.media-grid img{width:100%;height:100%;object-fit:cover}.media-grid .el-tag{margin-top:12px}.media-grid p{margin-top:9px;color:var(--text-secondary);height:42px;overflow:hidden}</style>
